 const[rankings,setRankings]=useState<Obj[]>([]),[card,setCard]=useState<Obj|null>(null),[startDate,setStartDate]=useState('2026-10-31'),[receipt,setReceipt]=useState('2026-10-31');
 const[amounts,setAmounts]=useState({illness:200000,accident:100000,cataract:60000}),[sliders,setSliders]=useState(false),[modal,setModal]=useState<Obj|null>(null),[login,setLogin]=useState(false),[passphrase,setPassphrase]=useState(''),[afterLogin,setAfterLogin]=useState<Phase>('card');
 const[recording,setRecording]=useState(false),[speaking,setSpeaking]=useState(false),[order,setOrder]=useState<Obj|null>(null),[audit,setAudit]=useState<Obj|null>(null),[auditVariant,setAuditVariant]=useState('m1_ped_addon_missing');
 const auditFieldLabels:Record<string,string>={uin:t('Plan identity','प्लान की पहचान'),inception:t('Policy start','पॉलिसी शुरू'),sum_insured:t('Sum insured','बीमा राशि'),age:t('Member age','सदस्य की उम्र'),sex:t('Member sex','सदस्य का लिंग'),declared:t('Declared conditions','घोषित बीमारियाँ'),instant_cover:t('Instant Cover add-on','Instant Cover ऐड-ऑन'),ped_months:t('Existing illness wait','पुरानी बीमारी की प्रतीक्षा'),initial_days:t('Initial waiting period','शुरुआती प्रतीक्षा'),specific_months:t('Listed procedure wait','सूचीबद्ध ऑपरेशन की प्रतीक्षा')};
 const[manualFields,setManualFields]=useState<Record<string,string>>({}),[manuallyChecked,setManuallyChecked]=useState(false);
 const manualLabels:Record<string,string>={uin:t('Plan UIN','प्लान का UIN'),inception:t('Policy start (YYYY-MM-DD)','पॉलिसी शुरू (YYYY-MM-DD)'),sum_insured:t('Sum insured (rupees)','बीमा राशि (रुपये)'),age:t('Member age','सदस्य की उम्र'),sex:t('Member sex (F/M/Other)','सदस्य का लिंग (F/M/Other)'),declared:t('Declared conditions (e.g. hypertension / None)','घोषित बीमारियाँ (जैसे hypertension / None)'),instant_cover:t('Instant Cover (Yes/No)','Instant Cover (Yes/No)'),ped_months:t('PED waiting months','पुरानी बीमारी की प्रतीक्षा (महीने)'),initial_days:t('Initial waiting days','शुरुआती प्रतीक्षा (दिन)'),specific_months:t('Specific waiting months','सूचीबद्ध रोग की प्रतीक्षा (महीने)')};
