 const[notifications,setNotifications]=useState<Obj[]>([]),[paymentMethod,setPaymentMethod]=useState('UPI'),[processing,setProcessing]=useState(false),[phoneNotice,setPhoneNotice]=useState<Obj|null>(null);
 const[liveHeard,setLiveHeard]=useState(''),[liveUnderstood,setLiveUnderstood]=useState(''),[toast,setToast]=useState('');
 const[completion,setCompletion]=useState<Obj|null>(null),[auditAcknowledged,setAuditAcknowledged]=useState(false);
