 const recorder=useRef<MediaRecorder|null>(null),recordStart=useRef(0),stopRequested=useRef(false),recordTimer=useRef<ReturnType<typeof setTimeout>|null>(null),audioPlayer=useRef<HTMLAudioElement|null>(null),fileInput=useRef<HTMLInputElement|null>(null),audioURL=useRef('');
 const api=async(path:string,init:RequestInit={},auth=token)=>{
  const res=await fetch(path,{...init,signal:init.signal||AbortSignal.timeout(135000),headers:{...(auth?{Authorization:`Bearer ${auth}`}:{ }),...(!(init.body instanceof FormData)&&init.body?{'Content-Type':'application/json'}:{}),...init.headers}});
  if(!res.ok){const b=await res.json().catch(()=>({}));
   if(res.status===409&&b.detail?.code==='review_required'){
    const current=await fetch(`/api/journeys/${localStorage.getItem('pc_jid')||jid}`,{headers:{Authorization:`Bearer ${auth}`},signal:AbortSignal.timeout(15000)});
    if(current.ok){const fresh=await current.json();setJourney(fresh);setReviewFocusId(b.detail.line_id);setPhase(fresh.node.key==='review'?'review':'interview');setNotice('');setError('');setModal(null);setLogin(false);throw new ReviewRedirect();}
   }
   throw new Error(typeof b.detail==='string'?b.detail:t('Something went wrong. Please try again.','फिर से कोशिश करें।'));}return res;
 };
 const post=async(path:string,body?:Obj,auth=token)=>(await api(path,{method:'POST',body:JSON.stringify(body||{})},auth)).json();
 const run=async(fn:()=>Promise<any>)=>{if(busy)return;setBusy(true);setError('');try{return await fn();}catch(e){if(!(e instanceof ReviewRedirect))setError(e instanceof Error?e.message:'Please try again');}finally{setBusy(false);}};
 const infer=(j:Obj):Phase=>j.node.key!=='review'?'interview':j.lines.some((line:Obj)=>!line.confirmed)?'review':j.completion?'complete':j.selection?'card':'review';
 const refresh=async(go?:Phase)=>{const j=await(await api(`/api/journeys/${jid}`)).json();setJourney(j);if(go)setPhase(go);return j;};
 const dateText=(v:string)=>new Intl.DateTimeFormat(hi?'hi-IN':'en-IN',{day:'numeric',month:'long',year:'numeric'}).format(new Date(v+'T12:00:00'));
 const stopAudio=()=>{speechGeneration.current++;audioPlayer.current?.pause();setSpeaking(false);if(audioURL.current){URL.revokeObjectURL(audioURL.current);audioURL.current='';}};
 useEffect(()=>{window.scrollTo({top:0,behavior:'instant'});setNotice('');setError('');},[phase,journey?.node.key]);
 useEffect(()=>{document.documentElement.lang=lang;localStorage.setItem('pc_lang',lang)},[lang]);
 useEffect(()=>{fetch('/api/ready').then(r=>r.json()).then(setReady).catch(()=>{});if(token&&jid){api(`/api/journeys/${jid}`).then(r=>r.json()).then(j=>{setJourney(j);setPhase(infer(j));if(j.selection){setStartDate(j.selection.d0);setReceipt(j.selection.receipt);setCompletion(j.completion||null);if(j.saved)api(`/api/journeys/${jid}/audit/latest`).then(r=>r.json()).then(result=>{setAudit(result);if(!j.completion)setPhase('audit');}).catch(()=>{});}}).catch(()=>{localStorage.removeItem('pc_token');localStorage.removeItem('pc_jid');setToken('');setJid('');});}},[]);
 const speak=async(lineId?:string)=>{if(!jid)return;stopAudio();const generation=speechGeneration.current;try{const r=await api(`/api/journeys/${jid}/speak`,{method:'POST',body:JSON.stringify(lineId?{line_id:lineId}:{})});if(r.status===204||generation!==speechGeneration.current)return;const blob=await r.blob();if(generation!==speechGeneration.current)return;const url=URL.createObjectURL(blob);audioURL.current=url;const a=new Audio(url);audioPlayer.current=a;a.onended=()=>setSpeaking(false);await a.play();setSpeaking(true);}catch{setSpeaking(false);}};
 useEffect(()=>{if((phase==='interview'||phase==='review')&&journey?.node.key){void speak();}return()=>stopAudio();},[journey?.node.key,phase]);
 useEffect(()=>{if(phase==='card'&&jid)api(`/api/journeys/${jid}/card`).then(r=>r.json()).then(setCard).catch(e=>setError(e.message));},[phase,jid]);
 const begin=()=>run(async()=>{let id=jid,auth=token;if(!id||!auth){const s=await post('/api/session',{lang},'');id=s.journey_id;auth=s.token;setJid(id);setToken(auth);localStorage.setItem('pc_token',auth);localStorage.setItem('pc_jid',id);}await post(`/api/journeys/${id}/consent`,consent,auth);const j=await(await api(`/api/journeys/${id}`,{},auth)).json();setJourney(j);setPhase('interview');});

 const answer=async(value:string)=>{stopAudio();const result=await(await api(`/api/journeys/${jid}/answer`,{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({text:value})})).json();if(result.accepted){setText('');setPhoto(null);setNotice('');const j=await refresh();setLiveHeard(value);setLiveUnderstood(String(j.slots[journey?.node.key]||value));if(j.node.key==='review')setPhase('review');}else setNotice(result.fallback);};
 const send=()=>run(()=>answer(text));
 const stopRecord=()=>{stopRequested.current=true;if(recordTimer.current)clearTimeout(recordTimer.current);if(recorder.current?.state==='recording')recorder.current.stop();};
 const startRecord=async()=>{if(busy)return;discardRecording.current=false;stopRequested.current=false;stopAudio();setError('');try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});const type=['audio/webm;codecs=opus','audio/mp4','audio/ogg;codecs=opus'].find(x=>MediaRecorder.isTypeSupported(x));const r=new MediaRecorder(stream,type?{mimeType:type}:{});recorder.current=r;const chunks:BlobPart[]=[];r.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};r.onstop=async()=>{setRecording(false);stream.getTracks().forEach(x=>x.stop());if(discardRecording.current)return;const duration=Math.min(25,(performance.now()-recordStart.current)/1000);if(duration<.3)return;const data=new FormData();data.append('audio',new Blob(chunks,{type:r.mimeType}),'voice.'+(r.mimeType.includes('mp4')?'m4a':'webm'));data.append('duration',duration.toFixed(2));await run(async()=>{const out=await(await api(`/api/journeys/${jid}/voice`,{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:data})).json();if(out.transcript)setLiveHeard(out.transcript);if(out.accepted){const j=await refresh();setLiveUnderstood(String(j.slots[journey?.node.key]||''));if(j.node.key==='review')setPhase('review');}else setNotice(out.fallback);});};recordStart.current=performance.now();r.start();setRecording(true);recordTimer.current=setTimeout(stopRecord,25000);if(stopRequested.current)r.stop();}catch{setNotice(t('Microphone unavailable. Tap an answer or type below.','माइक उपलब्ध नहीं है। नीचे चुनें या लिखें।'));}};
 const uploadPhoto=(file:File)=>run(async()=>{stopAudio();const bitmap=await createImageBitmap(file);const scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=bitmap.width*scale;canvas.height=bitmap.height*scale;canvas.getContext('2d')!.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const blob=await new Promise<Blob>(resolve=>canvas.toBlob(b=>resolve(b!),'image/jpeg',.85));if(preview)URL.revokeObjectURL(preview);setPreview(URL.createObjectURL(blob));const form=new FormData();form.append('image',blob,'strip.jpg');const result=await(await api(`/api/journeys/${jid}/photo`,{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:form})).json();setPhoto(result);});
 const chooseMedicine=(i:number)=>run(async()=>{await post(`/api/journeys/${jid}/medicine/choose`,{candidate:i});setPhoto(null);const j=await refresh();setLiveHeard(t('Medicine photo','दवा की फोटो'));setLiveUnderstood(j.slots.medicine);});
 const pendingLine=journey?.lines?.find((l:Obj)=>l.id===reviewFocusId&&!l.confirmed)||journey?.lines?.find((l:Obj)=>!l.confirmed);const confirmedCount=journey?.lines?.filter((l:Obj)=>l.confirmed).length||0;
 useEffect(()=>{if(phase==='review'&&pendingLine&&['conditions','since','medicine','frequency'].includes(pendingLine.key))void speak(pendingLine.id);return()=>stopAudio();},[phase,pendingLine?.id]);
 const confirm=()=>run(async()=>{await post(`/api/lines/${pendingLine.id}/confirm`,{version:pendingLine.version});await refresh();setReviewFocusId(null);setToast(t('Saved ✓','सहेजा गया ✓'));setTimeout(()=>setToast(''),1600);});
