 const choosePlan=(plan_id:string)=>run(async()=>{setNotice('');const result=await post(`/api/journeys/${jid}/select`,{plan_id,d0:startDate,receipt});setCard(result);await refresh('card');});
 const saveThen=(next:Phase)=>{if(journey?.saved){setPhase(next);return;}setAfterLogin(next);setLogin(true);};
 const save=()=>run(async()=>{await post(`/api/journeys/${jid}/save`,{passphrase});setPassphrase('');setLogin(false);await refresh(afterLogin);setNotice(t('Saved in this browser’s private demo session.','इस ब्राउज़र के निजी डेमो सत्र में सहेजा गया।'));});
 const requestAdvisor=()=>run(async()=>{let id=jid,auth=token;if(!id||!auth){const s=await post('/api/session',{lang},'');id=s.journey_id;auth=s.token;setJid(id);setToken(auth);localStorage.setItem('pc_token',auth);localStorage.setItem('pc_jid',id);}const result=await post(`/api/journeys/${id}/advisor`,{},auth);setModal({title:t('Callback request recorded','कॉलबैक अनुरोध दर्ज हुआ'),text:t(result.message,'अनुरोध डेमो संचालक के लिए दर्ज किया गया है। इस हैकाथॉन डेमो में कोई लाइसेंस प्राप्त सलाहकार जुड़ा नहीं है।'),request:result.request_id});});
 const makeOrder=()=>run(async()=>{const result=await post(`/api/journeys/${jid}/pay/initiate`);setOrder(result);localStorage.setItem('pc_order_id',result.order_id);});
 const completePayment=()=>run(async()=>{setProcessing(true);try{await new Promise(r=>setTimeout(r,2000));const result=await post(`/api/journeys/${jid}/pay/${order!.order_id}/complete`,{method:paymentMethod});setOrder(result);setNotifications(await(await api(`/api/journeys/${jid}/notifications`)).json());setPhoneNotice(result.notification);setTimeout(()=>setPhoneNotice(null),6500);}finally{setProcessing(false);}});
 const runAudit=(file?:File)=>run(async()=>{stopAudio();setAuditAcknowledged(false);setCompletion(null);const data=new FormData();if(file)data.append('policy',file);else data.append('variant',auditVariant);setAudit(await(await api(`/api/journeys/${jid}/audit`,{method:'POST',body:data})).json());});
 const finishReview=()=>run(async()=>{const result=audit?.audit_id?audit:await(await api(`/api/journeys/${jid}/audit/latest`)).json();setAudit(result);const saved=await post(`/api/journeys/${jid}/finish`,{audit_id:result.audit_id,acknowledged:!result.flags?.length||auditAcknowledged});setCompletion(saved);await refresh('complete');});
 const showFact=(fact:Obj)=>setModal({title:t('Why this number?','यह संख्या क्यों?'),fact});

 const stepIndex=phase==='consent'||phase==='member'||phase==='interview'?0:phase==='review'?1:phase==='ranking'?2:phase==='audit'||phase==='complete'?4:3;
 const flow=[{label:t('Talk','बात'),icon:Mic},{label:t('Check','जाँच'),icon:CheckCircle2},{label:t('Compare','तुलना'),icon:SlidersHorizontal},{label:t('Promise Card','वादा कार्ड'),icon:ShieldCheck},{label:t('Policy check','पॉलिसी जाँच'),icon:FileSearch}];
 const loadNotices=async()=>{if(jid)setNotifications(await(await api(`/api/journeys/${jid}/notifications`)).json());};
